(function executeRule(current, previous /*null when async*/ ) {


    var chgType = '';
    var usr = gs.getUserID();

    if (gs.hasRole('spm_cm_policy')) {
        chgType = 'policy';

    }
    if (gs.hasRole('spm_cm_organizational')) {
        chgType += ',' + 'organizational';
    }
    if (gs.hasRole('spm_cm_technology')) {
        chgType += ',' + 'technology';
    }
    if (gs.hasRole('spm_cm_strategic_plan')) {
        chgType += ',' + 'strategic_plan';
    }
    if (gs.hasRole('spm_cm_3rd_party_or_contractural')) {
        chgType += ',' + 'third_party_or_contractual_partner';
    }
    if (gs.hasRole('spm_cm_financial_product')) {
        chgType += ',' + 'financial_product';
    }
    if (gs.hasRole('spm_cm_procedure')) {
        chgType += ',' + 'procedure';
    }
    if (gs.hasRole('spm_cm_business_process')) {
        chgType += ',' + 'business_process';
    }
    if (gs.hasRole('spm_cm_regulatory')) {
        chgType += ',' + 'regulatory';
    }

    if (gs.hasRole('spm_cm_confidential')) {

        current.addEncodedQuery('sys_class_nameINjavascript:getValidProjectClasses()^u_change_typeIN' + chgType + '^ORu_change_type=^u_groupLIKEjavascript:getMyGroups()^ORu_groupISEMPTY');
    } else if (chgType == '') {

        current.addEncodedQuery('sys_class_nameINjavascript:getValidProjectClasses()^u_change_typeNOT INpolicy,organizational,technology,strategic_plan,third_party_or_contractual_partner,financial_product,business_process,procedure,regulatory^ORu_change_type=^u_groupLIKEjavascript:getMyGroups()^ORu_groupISEMPTY^u_confidential=false');
    } else {

        current.addEncodedQuery('sys_class_nameINjavascript:getValidProjectClasses()^u_change_typeIN' + chgType + '^ORu_change_type=^u_groupLIKEjavascript:getMyGroups()^ORu_groupISEMPTY^u_confidential=false');
		//current.addEncodedQuery('sys_class_nameINjavascript:getValidProjectClasses()^u_change_typeIN' + chgType + '^ORu_change_type=^u_confidential=false');
    }


    /*if (gs.hasRole('spm_cm_confidential')) {
        current.addEncodedQuery('sys_class_name=pm_project^u_change_typeIN' + chgType + '^ORu_change_type=^ORdemand.opened_by=' + usr + '^u_groupLIKEjavascript:getMyGroups()^ORu_groupISEMPTY^ORdemand.opened_by=' + usr);
    } else {

        //current.addEncodedQuery('sys_class_name=dmn_demand^u_imp_typeIN' + chgType + '^ORu_imp_type=^ORopened_by=' + usr + '^u_confidential=false^ORopened_by=' + usr + '^u_groupLIKEjavascript:getMyGroups()^ORu_groupISEMPTY^ORopened_by=' + usr);
		current.addEncodedQuery('sys_class_name=pm_project^u_change_typeIN' + chgType + '^ORu_change_type=^ORdemand.opened_by=' + usr + '^ORdemand.collaboratorsLIKE' + usr + '^u_confidential=false^ORdemand.opened_by=' + usr + '^ORdemand.collaboratorsLIKE' + usr + '^u_groupLIKEjavascript:getMyGroups()^ORu_groupISEMPTY^ORdemand.opened_by=' + usr +'^ORdemand.collaboratorsLIKE' + usr);

    }*/

})(current, previous);
